package local.prominence.hourglass;
import com.google.gson.JsonParser;import java.io.InputStreamReader;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.security.MessageDigest;import java.util.*;import net.fabricmc.loader.api.FabricLoader;import org.objectweb.asm.tree.ClassNode;import org.spongepowered.asm.mixin.extensibility.*;
public final class BalanceGuard implements IMixinConfigPlugin {
 private boolean hourglass,faceless;
 private boolean matches(String mod,String version){try(var in=getClass().getResourceAsStream("/hourglass-pins.json")){var loader=FabricLoader.getInstance();if(!loader.getModContainer("minecraft").orElseThrow().getMetadata().getVersion().getFriendlyString().equals("1.20.1"))return false;var c=loader.getModContainer(mod).orElseThrow();if(!c.getMetadata().getVersion().getFriendlyString().equals(version))return false;var pins=JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject().getAsJsonObject(mod);for(var x:pins.entrySet()){var bytes=Files.readAllBytes(c.findPath(x.getKey()).orElseThrow());if(!HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)).equals(x.getValue().getAsString()))return false;}return true;}catch(Exception|LinkageError e){return false;}}
 public void onLoad(String p){hourglass=matches("prominentbase","4.1.1");faceless=matches("eldritch_end","0.3.4");org.slf4j.LoggerFactory.getLogger("Prominence compatibility").info("Hourglass balance: {}; Faceless damage: {}",hourglass,faceless);}
 public boolean shouldApplyMixin(String t,String m){return m.endsWith("FacelessMixin")?faceless:hourglass;}public String getRefMapperConfig(){return null;}public List<String> getMixins(){return null;}public void acceptTargets(Set<String>a,Set<String>b){}public void preApply(String t,ClassNode n,String m,IMixinInfo i){}public void postApply(String t,ClassNode n,String m,IMixinInfo i){}
}